# logistic_selectivity ----
## Setup ----
# No setup required.

## IO correctness ----
test_that("`logistic_selectivity()` works with correct inputs", {
  #' @description Test that `logistic_selectivity(40.5, 20.5, 0.2)` returns the logistic function of 0.2 * (40.5 - 20.5) = 4, about 0.982.
  expect_equal(
    object = FIMS:::logistic_selectivity(40.5, 20.5, 0.2),
    expected = stats::plogis(4)
  )
  #' @description Test that a negative slope gives a descending curve, so `logistic_selectivity(40.5, 20.5, -0.2)` returns the logistic function of -4, about 0.018.
  expect_equal(
    object = FIMS:::logistic_selectivity(40.5, 20.5, -0.2),
    expected = stats::plogis(-4)
  )
  #' @description Test that `logistic_selectivity()` returns 0.5 at the inflection point.
  expect_equal(
    object = FIMS:::logistic_selectivity(4, 4, 1.7),
    expected = 0.5
  )
})

## Edge handling ----
# No edge cases to test.

## Error handling ----
# No built-in errors to test.

# double_logistic_selectivity ----
## Setup ----
# No setup required.

## IO correctness ----
test_that("`double_logistic_selectivity()` works with correct inputs", {
  #' @description Test that `double_logistic_selectivity()` is near 0 far below both inflection points.
  expect_lt(
    object = FIMS:::double_logistic_selectivity(0, 4, 2, 10, 2),
    expected = 1e-3
  )
  #' @description Test that `double_logistic_selectivity()` is near 1 between the 2 inflection points.
  expect_gt(
    object = FIMS:::double_logistic_selectivity(7, 4, 2, 10, 2),
    expected = 0.99
  )
  #' @description Test that `double_logistic_selectivity()` is the product of its 2 limbs, so with equal inflection points and slopes each limb is 0.5 and the result is 0.25.
  expect_equal(
    object = FIMS:::double_logistic_selectivity(5, 5, 1, 5, 1),
    expected = 0.25
  )
})

## Edge handling ----
# No edge cases to test.

## Error handling ----
# No built-in errors to test.

# age_specific_selectivity ----
## Setup ----
# No setup required.

## IO correctness ----
test_that("`age_specific_selectivity()` works with correct inputs", {
  #' @description Test that `age_specific_selectivity()` returns 0.5 at every age when each logit value is 0.
  expect_equal(
    object = FIMS:::age_specific_selectivity(1:3, c(0, 0, 0)),
    expected = rep(0.5, 3)
  )
  #' @description Test that `age_specific_selectivity()` is the inverse logit, so `qlogis(0.9)` returns 0.9.
  expect_equal(
    object = FIMS:::age_specific_selectivity(1, stats::qlogis(0.9)),
    expected = 0.9
  )
})

## Edge handling ----
test_that("`age_specific_selectivity()` returns correct outputs for edge cases", {
  #' @description Test that `age_specific_selectivity()` uses a single logit_sel_at_age value for every age.
  expect_equal(
    object = FIMS:::age_specific_selectivity(1:4, 0),
    expected = rep(0.5, 4)
  )
})

## Error handling ----
test_that("`age_specific_selectivity()` returns correct error messages", {
  #' @description Test that `age_specific_selectivity()` errors when the number of values is neither 1 nor 1 per age.
  expect_error(
    object = FIMS:::age_specific_selectivity(1:4, c(0, 1)),
    regexp = "1 value per age"
  )
})
